import { resolve } from 'node:path';
import { defineConfig } from 'vite';
import { cloudflare } from '@cloudflare/vite-plugin';
import vinext from 'vinext';
import { imagesOptimizer } from '@vinext/cloudflare/images/images-optimizer';

export default defineConfig({
  plugins: [
    // The approved static PNG is generated by scripts/generate-brand-og.ts.
    // Substituting the route module avoids evaluating Node filesystem I/O on Workers.
    {
      name: 'agency-rendering-inputs',
      enforce: 'pre',
      resolveId(id, importer) {
        if (id === './blog-files' && importer?.endsWith('/src/lib/blog.ts')) {
          return resolve('cloudflare/agency/blog-files.mjs');
        }
      },
      transform(_code, id) {
        if (id.split('?')[0].endsWith('/src/app/opengraph-image.tsx')) {
          return `export const size = {width:1200,height:630}; export const contentType = 'image/png';
            export default async function() { const { env } = await import('cloudflare:workers');
            return env.ASSETS.fetch('https://assets.invalid/brand/product-og.png'); }`;
        }
      },
    },
    vinext({ images: { optimizer: imagesOptimizer() }, react: { compiler: true } }),
    cloudflare({ configPath: './cloudflare/agency/wrangler.jsonc', viteEnvironment: { name: 'rsc', childEnvironments: ['ssr'] } }),
  ],
  resolve: { alias: { '@': resolve('src') } },
});
